static u32 native_function(u32 retail) {
    u32 lo = 0, hi = sly1::sly1_native_function_address_count;
    while (lo < hi) {
        const u32 mid = lo + (hi - lo) / 2;
        const auto& entry = sly1::sly1_native_function_addresses[mid];
        if (entry.retail_address < retail) lo = mid + 1;
        else hi = mid;
    }
    if (lo < sly1::sly1_native_function_address_count &&
        sly1::sly1_native_function_addresses[lo].retail_address == retail)
        return sly1::sly1_native_function_addresses[lo].native_address;
    return 0;
}

